package gateway

// U7 / channels-spec-r8 FR-054, US-6 AS1, S-50: a saved allowed sender must
// match individually. The chief ruled commas AND whitespace are separators;
// the field's help promises comma-separated IDs. These exact IDs are the U7
// brief's datasets, not values generated by the implementation under test.

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/elicify-ai/omnipus/pkg/bus"
	"github.com/elicify-ai/omnipus/pkg/channels"
	"github.com/elicify-ai/omnipus/pkg/config"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestU7_ConfigureAllowFromSavesListAndAdmitsSecondSender(t *testing.T) {
	cases := []struct {
		name string
		text string
		want []string
	}{
		{
			name: "space_separated",
			text: "200000000000000002 200000000000000003",
			want: []string{"200000000000000002", "200000000000000003"},
		},
		{
			name: "comma_separated",
			text: "200000000000000001,200000000000000002,200000000000000005",
			want: []string{"200000000000000001", "200000000000000002", "200000000000000005"},
		},
	}
	for _, platform := range []string{"discord", "telegram"} {
		t.Run(platform, func(t *testing.T) {
			for _, tc := range cases {
				t.Run(tc.name, func(t *testing.T) {
					// Disabled keeps this test at the save/read/load boundary;
					// it needs no network login and makes no reload-lifecycle claim.
					seed := fmt.Sprintf(`{"version":1,"agents":{"defaults":{},"list":[]},"providers":[],"channels":{%q:{"type":%q,"enabled":false,"token_ref":"u7-existing-token","allow_from":["200000000000000099"]}}}`, platform, platform)
					api := newChannelTestAPI(t, seed)
					t.Setenv("OMNIPUS_HOME", api.homePath)
					payload, err := json.Marshal(map[string]any{"allow_from": tc.text})
					require.NoError(t, err)
					request := httptest.NewRequest(http.MethodPut, "/api/v1/channels/"+platform+"/configure", strings.NewReader(string(payload)))
					request.Header.Set("Content-Type", "application/json")
					written := httptest.NewRecorder()
					api.HandleChannels(written, request)
					require.Equal(t, http.StatusOK, written.Code, "instrument: valid Configure request must save; body=%s", written.Body.String())

					wantJSON, err := json.Marshal(tc.want)
					require.NoError(t, err)
					readback := httptest.NewRecorder()
					api.HandleChannels(readback, httptest.NewRequest(http.MethodGet, "/api/v1/channels/"+platform, nil))
					require.Equal(t, http.StatusOK, readback.Code, readback.Body.String())
					var response map[string]json.RawMessage
					require.NoError(t, json.Unmarshal(readback.Body.Bytes(), &response))
					assert.JSONEq(t, string(wantJSON), string(response["allow_from"]),
						"U7: GET must return the exact allowed-ID list, not one unsplit string")

					path := filepath.Join(api.homePath, "config.json")
					saved, err := os.ReadFile(path)
					require.NoError(t, err)
					var root map[string]json.RawMessage
					require.NoError(t, json.Unmarshal(saved, &root))
					var instances map[string]json.RawMessage
					require.NoError(t, json.Unmarshal(root["channels"], &instances))
					var stored map[string]json.RawMessage
					require.NoError(t, json.Unmarshal(instances[platform], &stored))
					assert.JSONEq(t, string(wantJSON), string(stored["allow_from"]),
						"U7: raw config.json must contain the exact JSON list; a GET-only projection cannot fix this")

					loaded, err := config.LoadConfig(path)
					require.NoError(t, err, "instrument: the just-saved config must load")
					instance := loaded.Channels[platform]
					assert.Equal(t, tc.want, []string(instance.AllowFrom),
						"U7: the saved list must reach the next adapter's config without coalescing IDs")
					second := bus.SenderInfo{Platform: platform, PlatformID: tc.want[1], CanonicalID: platform + ":" + tc.want[1]}
					outsider := bus.SenderInfo{Platform: platform, PlatformID: "200000000000000099", CanonicalID: platform + ":200000000000000099"}

					// Positive and negative instrument controls: matching must be
					// capable of distinguishing these exact structured senders.
					control := channels.NewBaseChannel(platform, nil, bus.NewMessageBus(), tc.want)
					require.True(t, control.IsAllowedSender(second), "instrument: separately listed second ID is matchable")
					require.False(t, control.IsAllowedSender(outsider), "instrument: a nonempty list rejects an unlisted ID")
					actual := channels.NewBaseChannel(platform, instance, bus.NewMessageBus(), instance.AllowFrom)
					assert.True(t, actual.IsAllowedSender(second),
						"FR-054/U7: second allowed sender %s must not be refused after Configure", second.CanonicalID)
					assert.False(t, actual.IsAllowedSender(outsider),
						"FR-054/U7: normalization must not admit an old, now-unlisted sender")
				})
			}
		})
	}
}

func TestU7_ConfigureAllowFromHonorsWhatsAppCommaOnly(t *testing.T) {
	// Chief option B (2026-11-02 06:38Z) supplies these exact phone/Discord
	// literals and the WhatsApp comma-only exception. Preserve internal spaces;
	// no phone-to-JID rewrite is specified. This tests saving, not phone/JID
	// alias admission: the native handleIncoming matches evt.Info.Sender.String().
	cases := []struct {
		name     string
		platform string
		input    any
		want     []string
	}{
		{
			name: "whatsapp_single_spaced_phone", platform: "whatsapp",
			input: "+1 234 567", want: []string{"+1 234 567"},
		},
		{
			name: "whatsapp_two_comma_separated_spaced_phones", platform: "whatsapp",
			input: "+1 234 567, +4 987 654", want: []string{"+1 234 567", "+4 987 654"},
		},
		{
			name: "discord_spaces_still_separate_ids", platform: "discord",
			input: "111 222", want: []string{"111", "222"},
		},
		{
			name: "whatsapp_comma_separated_jids_unchanged", platform: "whatsapp",
			input: "1234567@s.whatsapp.net, 4987654@s.whatsapp.net",
			want:  []string{"1234567@s.whatsapp.net", "4987654@s.whatsapp.net"},
		},
		{
			name: "whatsapp_proper_phone_list_unchanged", platform: "whatsapp",
			input: []string{"+1 234 567", "+4 987 654"}, want: []string{"+1 234 567", "+4 987 654"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			// Disabled keeps real WhatsApp pairing/network outside this boundary.
			seed := fmt.Sprintf(`{"version":1,"agents":{"defaults":{},"list":[]},"providers":[],"channels":{%q:{"type":%q,"enabled":false,"token_ref":"u7-existing-token","allow_from":["old-sender"]}}}`, tc.platform, tc.platform)
			api := newChannelTestAPI(t, seed)
			t.Setenv("OMNIPUS_HOME", api.homePath)
			payload, err := json.Marshal(map[string]any{"allow_from": tc.input})
			require.NoError(t, err)
			request := httptest.NewRequest(http.MethodPut, "/api/v1/channels/"+tc.platform+"/configure", strings.NewReader(string(payload)))
			request.Header.Set("Content-Type", "application/json")
			written := httptest.NewRecorder()
			api.HandleChannels(written, request)
			require.Equal(t, http.StatusOK, written.Code, "instrument: valid Configure request must save; body=%s", written.Body.String())

			wantJSON, err := json.Marshal(tc.want)
			require.NoError(t, err)
			readback := httptest.NewRecorder()
			api.HandleChannels(readback, httptest.NewRequest(http.MethodGet, "/api/v1/channels/"+tc.platform, nil))
			require.Equal(t, http.StatusOK, readback.Code, readback.Body.String())
			var response map[string]json.RawMessage
			require.NoError(t, json.Unmarshal(readback.Body.Bytes(), &response))
			assert.JSONEq(t, string(wantJSON), string(response["allow_from"]),
				"chief option B: GET must retain each WhatsApp phone's internal spaces")

			path := filepath.Join(api.homePath, "config.json")
			saved, err := os.ReadFile(path)
			require.NoError(t, err)
			var root map[string]json.RawMessage
			require.NoError(t, json.Unmarshal(saved, &root))
			var instances map[string]json.RawMessage
			require.NoError(t, json.Unmarshal(root["channels"], &instances))
			var stored map[string]json.RawMessage
			require.NoError(t, json.Unmarshal(instances[tc.platform], &stored))
			assert.JSONEq(t, string(wantJSON), string(stored["allow_from"]),
				"chief option B: raw config.json must save one entry per comma-separated WhatsApp ID")

			loaded, err := config.LoadConfig(path)
			require.NoError(t, err, "instrument: the just-saved config must load")
			instance, exists := loaded.Channels[tc.platform]
			require.True(t, exists, "instrument: selected platform must survive save/load")
			assert.Equal(t, tc.want, []string(instance.AllowFrom),
				"chief option B: exact platform-specific ID list must survive save/load")
		})
	}
}
